import { ContractJobType, ContractState } from './enums.js';

/**
 * ContractObject: The Unit of Demand
 * Defines a physical mission generated by a KnowledgeInventory deficit.
 */
export class Contract {
    constructor(data = {}) {
        this.contractId = data.contractId || `cnt_${Math.random().toString(36).substr(2, 9)}_${Date.now()}`;
        this.originId = data.originId || 'unknown';
        this.targetIntelId = data.targetIntelId || null;
        this.jobType = Object.values(ContractJobType).includes(data.jobType) 
            ? data.jobType 
            : ContractJobType.SURVEY;

        // Priority & Strategy
        this.priority = data.priority || 0;
        this.isCuriosity = data.isCuriosity || false;
        
        // Team Requirements
        this.minimumTeam = data.minimumTeam || []; // Roles required to start
        this.idealTeam = data.idealTeam || [];     // Roles for bonuses
        this.teamMembers = data.teamMembers || []; // Currently assigned NPC IDs
        
        // Resources & Budget
        this.resources = data.resources || { gold: 0, rations: 0 };
        
        // Lifecycle State
        this.status = Object.values(ContractState).includes(data.status)
            ? data.status
            : ContractState.GENERATED;
            
        this.expiration = data.expiration || 'NEXT_SHIFT';
        this.createdAt = data.createdAt || (window.EngineParams?.worldDay || 0);
        this.lastAttemptAt = data.lastAttemptAt || 0; // For Hysteresis
        
        // Completion Info
        this.successCriteria = data.successCriteria || 'FACT_FOUND';
    }

    /**
     * Serializes the contract for persistence.
     */
    serialize() {
        return JSON.stringify(this);
    }
}
